	// A 1.92 flag word -> the 1.90 word; a_dropped gets the bits 1.90 has no name for.
	template <std::size_t N>
	constexpr std::uint32_t Flags(std::uint32_t a_new, const FlagBit (&a_map)[N], std::uint32_t* a_dropped = nullptr)
	{
		std::uint32_t out = 0, dropped = 0, seen = 0;
		for (const FlagBit& b : a_map)
		{
			if ((a_new & b.newBit) == 0) { continue; }
			seen |= b.newBit;
			if (b.oldBit) { out |= b.oldBit; } else { dropped |= b.newBit; }
		}
		dropped |= a_new & ~seen;
		if (a_dropped) { *a_dropped = dropped; }
		return out;
	}

	// A 1.92 index -> the 1.90 index (-1 = none).
	template <std::size_t N>
	constexpr int Index(int a_new, const short (&a_map)[N]) { return a_new >= 0 && a_new < static_cast<int>(N) ? a_map[a_new] : -1; }
